export default {
  id: 'command-sample',
  name: 'command-sample',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'command',
      command: {
        name: 'upper',
        description: 'Uppercase the first element of the args array.',
        handler: (args: string[]) => (args[0] ?? '').toUpperCase()
      }
    });
  }
};
